Loss.create!([
  {date: "2016-05-27 04:00:00", amount: "62500000.0", title: "Attendance decreased at NC's Highpoint Market in response to HB2", slug: "highpoint-market", description: "", template: "\nNC loses even more money due to HB2.<br><br>\n\nAccounting for nearly 26% of the total losses to the state of North Carolina to date, the  loss of this  is yet another financial setback for the state over HB2.\n\n <blockquote class=\"template-quote\">\n\"\"Read more here: http://www.charlotteobserver.com/news/business/article69837702.html#storylink=cpy\"\n<br><br>\n- \n <a class=\"link\" href=\"\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe state continues to lose money over HB2.\n", sources: [{"link"=>"http://www.bizjournals.com/triad/news/2016/05/27/high-point-market-attendance-figures-released.html", "meta"=>{"publication"=>"Triangle Business Journal", "title"=>"High Point Market attendance figures released", "date"=>"5/27/16", "accessed"=>"9/9/16"}}, {"link"=>"http://www.hickoryrecord.com/news/crowd-thins-slightly-at-nc-furniture-market-after-lgbt-law/article_0063fe40-2429-11e6-bd3a-9baf79980be0.html", "meta"=>{"publication"=>"Hickory Record", "title"=>"Crowd thins slightly at NC furniture market after LGBT law", "date"=>"5/27/16", "accessed"=>"9/9/16"}}, {"link"=>"CUSTOM_CALC", "anchor"=>true}], active: false, featured: false},
  {date: "2016-05-20 04:00:00", amount: "1365034.125", title: "Citing HB2, Maroon 5 cancels NC shows", slug: "maroon-5", description: "", template: "\nHere's another unfortunate loss for the state of North Carolina.<br><br>\n\nContributing  $1,365,034 to the total of $236,363,156, the loss of this concert is painful for NC.\n\n <blockquote class=\"template-quote\">\n\"\"\"\n<br><br>\n- \n</blockquote>\n\nThe Maroon 5 in Raleigh and Charlotte is just one of recent losses for NC over HB2.\n", sources: [{"link"=>"http://www.wral.com/maroon-5-cancels-nc-shows-citing-hb2/15716462/", "meta"=>{"publication"=>"WRAL", "title"=>"Citing HB2, Maroon 5 cancels shows in Raleigh and Charlotte", "date"=>"5/20/16", "accessed"=>"9/9/16"}}, {"link"=>"http://www.charlotteobserver.com/entertainment/music-news-reviews/article78823022.html", "meta"=>{"publication"=>"Charlotte Observer", "title"=>"Maroon 5 cancels N.C. shows over HB2, calling decision ‘morally right", "date"=>"5/20/16", "accessed"=>"9/9/16", "author"=>"Theoden Janes"}}, {"link"=>"CUSTOM_CALC", "anchor"=>true}], active: false, featured: false},
  {date: "2016-04-05 04:00:00", amount: "44000000.0", title: "PayPal withdraws NC investment over HB2", slug: "paypal", description: "", template: "\nNC loses even more money due to HB2.<br><br>\n\nAccounting for nearly 19% of the total losses to the state of North Carolina to date, the  loss of this company expansion is but one of many recent hits related to HB2.\n\n <blockquote class=\"template-quote\">\n\"\"The new law perpetuates discrimination and it violates the values and principles that are at the core of PayPal’s mission and culture.  As a result, PayPal will not move forward with our planned expansion into Charlotte.\"\n<br><br>\n- Dan Schulman, President and CEO of PayPal.\n <a class=\"link\" href=\"https://www.paypal.com/stories/us/paypal-withdraws-plan-for-charlotte-expansion\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe state continues to lose money over HB2.\n", sources: [{"link"=>"http://www.hrc.org/blog/am-equality-tip-sheet-april-5-2016", "meta"=>{"publication"=>"Human Rights Campaign", "title"=>"#AM_Equality Tip Sheet: April 5, 2016", "date"=>"4/5/2016", "author"=>"HRC Staff", "accessed"=>"9/9/16"}}, {"link"=>"https://www.americanprogress.org/issues/lgbt/news/2016/04/13/135391/north-carolinas-discriminatory-h-b-2-threatens-more-than-half-billion-dollars-in-economic-activity/", "meta"=>{"publication"=>"Center for American Progress", "title"=>"North Carolina’s Discriminatory H.B. 2 Threatens More Than Half Billion Dollars in Economic Activity", "date"=>"4/13/2016", "author"=>"Shabab Ahmed Mirza, Sarah McBride, Laura E. Durso", "accessed"=>"9/9/16"}}], active: false, featured: false},
  {date: "2016-04-04 04:00:00", amount: "3000000.0", title: "Lionsgate moves move shoot out of NC because of HB2", slug: "lionsgate", description: "", template: "\nThe state of North Carolina reports another loss due to HB2.<br><br>\n\nContributing  $3,000,000 to the total of $236,363,156, the loss of this movie shoot hurts North Carolina.\n\n <blockquote class=\"template-quote\">\n\"\"We will be hard pressed to continue our relationship with North Carolina if this regressive law remains on the books\"\n<br><br>\n- Lionsgatevia Charlotte Observer\n <a class=\"link\" href=\"http://www.charlotteobserver.com/news/business/article69837702.html\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe state continues to lose money over HB2.\n", sources: [{"link"=>"http://www.fox46charlotte.com/news/local-news/116956922-story", "meta"=>{"publication"=>"Fox 46 of Charlotte", "title"=>"Lionsgate takes 100 jobs from NC due to HB2", "date"=>"4/4/16", "author"=>"Fox", "accessed"=>"9/9/16"}}, {"link"=>"https://www.americanprogress.org/issues/lgbt/news/2016/04/13/135391/north-carolinas-discriminatory-h-b-2-threatens-more-than-half-billion-dollars-in-economic-activity/", "meta"=>{"publication"=>"Center for American Progress", "title"=>"North Carolina’s Discriminatory H.B. 2 Threatens More Than Half Billion Dollars in Economic Activity", "date"=>"4/13/16", "author"=>"Shabab Ahmed Mirza, Sarah McBride, Laura E. Durso", "accessed"=>"9/9/16"}}], active: false, featured: false},
  {date: "2016-07-21 04:00:00", amount: "100000000.0", title: "The NBA moves 2017 All-Star Game out of North Carolina in response to HB2", slug: "nba-all-star-game", description: "", template: "\nHere's another unfortunate loss for the state of North Carolina.<br><br>\n\nContributing a massive $100,000,000 to the total of $236,363,156, the loss of this event hurts North Carolina.\n\n <blockquote class=\"template-quote\">\n\"\"The NBA has decided to relocate the 2017 All-Star Game from Charlotte with the hope of rescheduling for 2019.\n\nSince March, when North Carolina enacted HB2 and the issue of legal protections for the LGBT community in Charlotte became prominent, the NBA and the Charlotte Hornets have been working diligently to foster constructive dialogue and try to effect positive change. We have been guided in these discussions by the long-standing core values of our league. These include not only diversity, inclusion, fairness and respect for others but also the willingness to listen and consider opposing points of view.\n\nOur week-long schedule of All-Star events and activities is intended to be a global celebration of basketball, our league, and the values for which we stand, and to bring together all members of the NBA community -- current and former players, league and team officials, business partners, and fans. While we recognize that the NBA cannot choose the law in every city, state, and country in which we do business, we do not believe we can successfully host our All-Star festivities in Charlotte in the climate created by HB2.\n\nWe are particularly mindful of the impact of this decision on our fans in North Carolina, and who are among the most passionate in our league. It is also important to stress that the City of Charlotte and the Hornets organization have sought to provide an inclusive environment and that the Hornets will continue to ensure that all patrons -- including members of the LGBT community -- feel welcome while attending games and events in their arena.\n\nWe look forward to re-starting plans for our All-Star festivities in Charlotte for 2019 provided there is an appropriate resolution to this matter.\n\nThe NBA will make an announcement on the new location of the 2017 NBA All-Star Game in the coming weeks.\"\n<br><br>\n- NBA\n</blockquote>\n\nThe NBA All-Star Game in Charlotte is just one of recent losses for NC over HB2.\n", sources: [{"link"=>"http://www.forbes.com/sites/maurybrown/2016/07/22/the-economic-impact-of-charlotte-losing-nba-all-star-game-and-potentially-super-bowls-due-to-hb2/#6e66e6633f60", "meta"=>{"publication"=>"Forbes", "title"=>"The Economic Impact Of Charlotte Losing NBA All-Star Game, And Potentially Super Bowls Due To HB2", "date"=>"7/22/16", "author"=>"Maury Brown", "accessed"=>"9/9/16"}}, {"link"=>"https://www.washingtonpost.com/news/sports/wp/2016/07/21/report-nba-will-move-2017-all-star-game-from-charlotte-to-new-orleans-over-hb2-law/", "meta"=>{"publication"=>"Washington Post", "title"=>"NBA will move 2017 All-Star Game from Charlotte over HB2 law", "date"=>"7/21/16", "author"=>"Tim Bontemps", "accessed"=>"9/9/16"}}, {"link"=>"http://www.espn.com/nba/story/_/id/17120170/nba-moving-all-star-game-charlotte-north-carolina-bill", "meta"=>{"publication"=>"ESPN", "title"=>"NBA moves 2017 All-Star Game from Charlotte over HB2 bill", "date"=>"7/22/16", "accessed"=>"9/9/16"}}], active: false, featured: false},
  {date: "2016-04-08 04:00:00", amount: "700000.0", title: "Bruce Springsteen concert cancelled in protest of House Bill 2", slug: "bruce-springsteen", description: "Springsteen was scheduled to play Greensboro, but said he finds the passing of House Bill 2 unacceptable, and he is doing his part to push back.", template: "\nNC loses even more money due to HB2.<br><br>\n\nContributing  $700,000 to the total of $236,363,156, the loss of this concert hurts North Carolina.\n\n <blockquote class=\"template-quote\">\n\"\"Some things are more important than a rock show and this fight against prejudice and bigotry — which is happening as I write — is one of them. It is the strongest means I have for raising my voice in opposition to those who continue to push us backwards instead of forwards.\"\n<br><br>\n- Bruce Springsteen\n <a class=\"link\" href=\"http://brucespringsteen.net/news/2016/a-statement-from-bruce-springsteen-on-north-carolina\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe Bruce Springsteen concert in Greensboro is just one of recent losses for NC over HB2.\n", sources: [{"link"=>"http://money.cnn.com/2016/04/08/media/bruce-springsteen-north-carolina-show-canceled/", "meta"=>{"publication"=>"CNN Money", "title"=>"Bruce Springsteen cancels North Carolina concert over 'bathroom law'", "date"=>"4/8/16", "author"=>"Tom Kludt", "accessed"=>"9/9/16"}}, {"link"=>"https://www.americanprogress.org/issues/lgbt/news/2016/04/13/135391/north-carolinas-discriminatory-h-b-2-threatens-more-than-half-billion-dollars-in-economic-activity/", "meta"=>{"publication"=>"Center for American Progress", "title"=>"North Carolina’s Discriminatory H.B. 2 Threatens More Than Half Billion Dollars in Economic Activity", "date"=>"4/13/16", "author"=>"Shabab Ahmed Mirza, Sarah McBride, Laura E. Durso", "accessed"=>"9/9/16"}}], active: false, featured: false},
  {date: "2016-05-17 04:00:00", amount: "75900.7925", title: "Itzhak Perlman cancels NC concert", slug: "itzhak-perlman", description: "", template: "\nNC continues to lose money due to the controversial House Bill 2.<br><br>\n\nAccounting for nearly 0% of the total losses to the state of North Carolina to date, the  loss of this  is a painful reality for the state.\n\n <blockquote class=\"template-quote\">\n\"\"As my fans know, I have spent a lifetime advocating against discrimination towards those with physical disabilities and have been a vocal advocate for treating all people equally. As such, after great consideration, I have decided to cancel my May 18th concert in North Carolina with the North Carolina Symphony as a stand against House Bill 2. As Attorney General Loretta Lynch recently stated, and HB2 “is about a great deal more than just bathrooms. [It] is about the dignity and respect we accord our fellow citizens.” I couldn’t agree more and will look forward to returning to North Carolina when this discriminatory law is repealed.\"\n<br><br>\n- Itzhak Perlmanvia Facebook\n</blockquote>\n\nThe state continues to lose money over HB2.\n", sources: [{"link"=>"http://www.jewishjournal.com/culture/article/violinist_itzhak_perlman_scraps_n.c._concert_over_discriminatory_law", "meta"=>{"publication"=>"Jewish Journal", "title"=>"Violinist Itzhak Perlman scraps N.C. concert over ‘discriminatory’ law", "date"=>"5/17/16", "accessed"=>"9/9/16", "author"=>"Colleen Jenkins"}}, {"link"=>"http://www.npr.org/sections/deceptivecadence/2016/05/18/478556368/itzhak-perlman-on-canceling-in-north-carolina-i-had-to", "meta"=>{"publication"=>"NPR", "title"=>"Itzhak Perlman On Canceling In North Carolina: 'I Had To'", "date"=>"5/18/16", "accessed"=>"9/9/16", "author"=>"Anastasia Tsioulcas"}}, {"link"=>"CUSTOM_CALC"}], active: false, featured: false},
  {date: "2016-04-25 04:00:00", amount: "950000.0", title: "American Institute of Architects moves South Atlantic Region Conference out of Wilmington", slug: "aia-conference", description: "", template: "\nThings just keep getting worse for the state of NC over HB2.<br><br>\n\nAccounting for nearly 0% of the total losses to the state of North Carolina to date, the  loss of this  is but one of many recent hits related to HB2.\n\n <blockquote class=\"template-quote\">\n\"\"\"\n<br><br>\n- \n</blockquote>\n\nThis is but one of many recent losses for the state of NC related to HB2.\n", sources: [{"link"=>"http://www.wilmingtonbiz.com/hospitality/2016/04/26/hb2_loss_of_architect_conference_costs_wilmington_nearly_1m_estimates_show/14705", "meta"=>{"publication"=>"Wilmington Biz", "title"=>"HB2 Loss Of Architect Conference Costs Wilmington Nearly $1M, Estimates Show", "date"=>"4/26/16", "accessed"=>"9/9/16", "author"=>"Cece Nunn"}}, {"link"=>"http://www.aianc.org/government-updates/hb2-our-commitment-to-diversity-and-inclusionary-design-1", "meta"=>{"publication"=>"AIA NC", "title"=>"AIA South Atlantic to Move Conference From Wilmington Due to HB 2", "date"=>"4/25/16", "accessed"=>"9/9/16", "author"=>"David Crawford"}}], active: false, featured: false},
  {date: "2016-04-12 04:00:00", amount: "21400000.0", title: "HB2 causes cancellation of Deutsche Bank's planned Cary expansion", slug: "deutsche-bank", description: "After freezing jobs expansion in Cary over HB2, Deutsche Bank moves ahead with Florida expansion", template: "\nNorth Carolina reports further HB2 related losses.<br><br>\n\nContributing  $21,400,000 to the total of $236,363,156, the loss of this company expansion is painful for NC.\n\n <blockquote class=\"template-quote\">\n\"\"We take the commitment to building inclusive work environments seriously. We’re proud of our operations and employees in Cary and regret that as a result of this legislation we are unwilling to include North Carolina in our U.S. expansion plans for now. We very much hope to revisit our plans to grow this location in the near future.\"\n<br><br>\n- John Cryan, Co-Chief Executive Officer of Deutsche Bank.\n <a class=\"link\" href=\"https://www.db.com/usa/content/en/3639.html\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe Deutsche Bank expansion in Cary is just one of recent losses for NC over HB2.\n", sources: [{"link"=>"http://www.bizjournals.com/triangle/news/2016/07/27/three-months-after-hb2-jobs-freeze-in-cary.html", "meta"=>{"publication"=>"Triangle Business Journal", "title"=>"After freezing jobs expansion in Cary over HB2, Deutsche Bank moves ahead with Florida expansion", "date"=>"7/27/16", "author"=>"Lauren K. Ohnesorge", "accessed"=>"9/9/16"}}, {"link"=>"http://www.newsobserver.com/news/business/article71314817.html", "meta"=>{"publication"=>"The News and Observer", "title"=>"Economic impact of HB2 mushrooms in the Triangle", "date"=>"4/12/16", "author"=>"David Bracken and Paul A. Specht", "accessed"=>"9/9/16"}}, {"link"=>"https://www.americanprogress.org/issues/lgbt/news/2016/04/13/135391/north-carolinas-discriminatory-h-b-2-threatens-more-than-half-billion-dollars-in-economic-activity/", "meta"=>{"publication"=>"Center for American Progress", "title"=>"North Carolina’s Discriminatory H.B. 2 Threatens More Than Half Billion Dollars in Economic Activity", "date"=>"4/13/16", "author"=>"Shabab Ahmed Mirza, Sarah McBride, Laura E. Durso", "accessed"=>"9/9/16"}}], active: false, featured: false},
  {date: "2016-04-26 04:00:00", amount: "1500000.0", title: "W. K. Kellogg Foundation conference moved out of Asheville", slug: "w-k-kellogg-conference", description: "", template: "\nHere's another unfortunate loss for the state of North Carolina.<br><br>\n\nContributing  $1,500,000 to the total of $236,363,156, the loss of this  hurts North Carolina.\n\n <blockquote class=\"template-quote\">\n\"\"\"\n<br><br>\n- \n</blockquote>\n\nThe state continues to lose money over HB2.\n", sources: [{"link"=>"http://www.citizen-times.com/story/news/local/2016/04/25/hb2-costs-asheville-15m-conference/83513046/", "meta"=>{"publication"=>"Citizen Times", "title"=>"HB2 costs Asheville $1.5M conference", "date"=>"4/26/16", "accessed"=>"9/9/16", "author"=>"John Boyle"}}, {"link"=>"http://wlos.com/news/local/asheville-conference-estimated-to-have-15-million-impact-canceled-due-to-hb2", "meta"=>{"publication"=>"News 13 WLOS", "title"=>"Asheville conference estimated to have $1.5 million impact canceled due to HB2", "date"=>"4/25/16", "accessed"=>"9/9/16", "author"=>"Kimberly King and Krystyna Biassou"}}], active: false, featured: false},
  {date: "2016-04-25 04:00:00", amount: "872221.0", title: "Demi Lovato and Nick Jonas cancel NC concerts in response to HB2", slug: "demi-lovato-nick-jonas", description: "", template: "\nNC loses even more money due to HB2.<br><br>\n\nAccounting for nearly 0% of the total losses to the state of North Carolina to date, the  loss of this concert is but one of many recent hits related to HB2.\n\n <blockquote class=\"template-quote\">\n\"\"After much thought and deliberation, we have decided to cancel our Honda Civic Tour: Future Now shows in Raleigh and Charlotte. One of our goals for the tour has always been to create an atmosphere where every single attendee feels equal, included, and accepted for who they are.\"\n<br><br>\n- Demi Lovato and Nick Jonasvia Twitter\n <a class=\"link\" href=\"https://twitter.com/ddlovato/status/724705165186457600\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe state continues to lose money over HB2.\n", sources: [{"link"=>"http://www.rollingstone.com/music/news/nick-jonas-demi-lovato-cancel-north-carolina-shows-to-protest-hb2-20160425", "meta"=>{"publication"=>"Rolling Stone", "title"=>"Nick Jonas, Demi Lovato Cancel North Carolina Shows to Protest HB2", "date"=>"4/25/16", "accessed"=>"9/9/16", "author"=>"Daniel Kreps"}}, {"link"=>"http://www.charlotteobserver.com/entertainment/music-news-reviews/article73823087.html", "meta"=>{"publication"=>"Charlotte Observer", "title"=>"Demi Lovato, Nick Jonas Charlotte show canceled over HB2", "date"=>"4/25/16", "accessed"=>"9/9/16", "author"=>"Mark Price"}}, {"link"=>"CUSTOM_CALC"}], active: false, featured: false}
])
